class GymVm(private val ctx:Context):ViewModel(){
 var screen by mutableStateOf("home"); var selected by mutableStateOf<Exercise?>(null); var arabic by mutableStateOf(false); var query by mutableStateOf(""); var favorites by mutableStateOf(setOf<Int>()); var history by mutableStateOf(0)
 private val prefs=ctx.getSharedPreferences("wissam_gym",Context.MODE_PRIVATE)
 init{favorites=prefs.getStringSet("favorites",emptySet())?.mapNotNull{it.toIntOrNull()}?.toSet()?:emptySet();history=prefs.getInt("history",0)}
 fun toggleFavorite(e:Exercise){favorites=if(e.id in favorites)favorites-e.id else favorites+e.id;prefs.edit().putStringSet("favorites",favorites.map{it.toString()}.toSet()).apply()}
 fun complete(){history++;prefs.edit().putInt("history",history).apply()}
 fun open(e:Exercise){selected=e;screen="detail"}
}
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{GymTheme{GymRoot()}}}}
@Composable fun GymTheme(content: @Composable () -> Unit)=MaterialTheme(colorScheme=darkColorScheme(primary=Red,background=Black,surface=Charcoal,onSurface=Color.White),content=content)
@Composable fun GymRoot(){val context=LocalContext.current;val vm:GymVm=viewModel(factory=object:androidx.lifecycle.ViewModelProvider.Factory{override fun <T:ViewModel> create(c:Class<T>):T=GymVm(context) as T});val rtl=vm.arabic;CompositionLocalProvider(LocalLayoutDirection provides if(rtl)LayoutDirection.Rtl else LayoutDirection.Ltr){Scaffold(containerColor=Black,bottomBar={if(vm.screen!="detail")BottomNav(vm)}){p->Box(Modifier.padding(p)){when(vm.screen){"home"->Home(vm);"library"->Library(vm);"favorites"->Favorites(vm);"history"->History(vm);else->Detail(vm)}}}}}
@Composable fun Top(title:String,back:(()->Unit)?=null,action:()->Unit={}){Row(Modifier.fillMaxWidth().padding(18.dp),verticalAlignment=Alignment.CenterVertically){if(back!=null)IconButton(back){Icon(Icons.Default.ArrowBack,null)}else Icon(Icons.Default.FitnessCenter,null,tint=Red,modifier=Modifier.size(32.dp));Spacer(Modifier.width(10.dp));Text(title,fontSize=23.sp,fontWeight=FontWeight.Bold,modifier=Modifier.weight(1f));IconButton(action){Icon(Icons.Default.MoreVert,null)}}}
@Composable fun Home(vm:GymVm){Column(Modifier.fillMaxSize()){Top("WISSAM GYM",action={vm.arabic=!vm.arabic});LazyColumn(contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(16.dp)){item{Hero(vm)};item{SectionTitle(if(vm.arabic)"تمارين الصدر" else "Chest Training")};items(exercises.take(4)){ExerciseCard(it,vm)};item{SectionTitle(if(vm.arabic)"تقدمك" else "Your progress")};item{ProgressCard(vm)}}}}
@Composable fun Hero(vm:GymVm){Card(colors=CardDefaults.cardColors(containerColor=Charcoal),shape=RoundedCornerShape(26.dp)){Column(Modifier.background(Brush.linearGradient(listOf(Color(0xFF351016),Charcoal))).padding(22.dp)){Text(if(vm.arabic)"ابنِ صدراً أقوى" else "Build a stronger chest",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Text(if(vm.arabic)"خطة تدريب احترافية • 18 تمريناً" else "Professional training plan • 18 exercises",color=TextMuted);Spacer(Modifier.height(18.dp));Button({vm.screen="library"},colors=ButtonDefaults.buttonColors(containerColor=Red)){Text(if(vm.arabic)"ابدأ التدريب" else "Start training")}}}}
@Composable fun SectionTitle(t:String){Text(t,style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)}
@Composable fun ProgressCard(vm:GymVm){Row(Modifier.fillMaxWidth().background(Card,RoundedCornerShape(18.dp)).padding(18.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.EmojiEvents,null,tint=Red,modifier=Modifier.size(34.dp));Spacer(Modifier.width(14.dp));Column{Text(if(vm.arabic)"جلسات مكتملة" else "Completed sessions",fontWeight=FontWeight.Bold);Text(vm.history.toString(),color=Red,style=MaterialTheme.typography.headlineSmall)}}}
@Composable fun Library(vm:GymVm){Column{Top(if(vm.arabic)"مكتبة الصدر" else "Chest library");OutlinedTextField(vm.query,{vm.query=it},Modifier.fillMaxWidth().padding(horizontal=16.dp),singleLine=true,label={Text(if(vm.arabic)"بحث" else "Search")},leadingIcon={Icon(Icons.Default.Search,null)});LazyColumn(contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){items(exercises.filter{it.en.contains(vm.query,true)||it.ar.contains(vm.query,true)||it.target.contains(vm.query,true)}){ExerciseCard(it,vm)}}}}
@Composable fun Favorites(vm:GymVm){Column{Top(if(vm.arabic)"المفضلة" else "Favorites");val list=exercises.filter{it.id in vm.favorites};if(list.isEmpty())Text(if(vm.arabic)"لا توجد تمارين مفضلة بعد" else "No favorite exercises yet",Modifier.padding(24.dp),color=TextMuted);else LazyColumn(contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){items(list){ExerciseCard(it,vm)}}}}
@Composable fun History(vm:GymVm){Column{Top(if(vm.arabic)"السجل" else "History");Card(Modifier.padding(18.dp).fillMaxWidth(),colors=CardDefaults.cardColors(containerColor=Card)){Column(Modifier.padding(20.dp)){Text(if(vm.arabic)"إجمالي الجلسات" else "Total sessions",color=TextMuted);Text(vm.history.toString(),style=MaterialTheme.typography.displaySmall,color=Red,fontWeight=FontWeight.Bold);Text(if(vm.arabic)"يتم حفظ تقدمك محلياً على الجهاز" else "Your progress is stored locally on this device",color=TextMuted)}}}}
@Composable fun ExerciseCard(e:Exercise,vm:GymVm){Card(Modifier.fillMaxWidth().clickable{vm.open(e)},colors=CardDefaults.cardColors(containerColor=Card),shape=RoundedCornerShape(18.dp)){Row(Modifier.padding(15.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(62.dp).background(Color(0xFF351016),RoundedCornerShape(14.dp)),contentAlignment=Alignment.Center){Icon(Icons.Default.FitnessCenter,null,tint=Red,modifier=Modifier.size(32.dp))};Spacer(Modifier.width(14.dp));Column(Modifier.weight(1f)){Text(if(vm.arabic)e.ar else e.en,fontWeight=FontWeight.Bold);Text("${e.target} • ${e.equipment}",color=TextMuted,style=MaterialTheme.typography.bodySmall)};Icon(if(e.id in vm.favorites)Icons.Default.Favorite else Icons.Default.FavoriteBorder,null,tint=if(e.id in vm.favorites)Red else TextMuted)}}}
@Composable fun Detail(vm:GymVm){val e=vm.selected?:return;var sets by remember{mutableStateOf("3")};var reps by remember{mutableStateOf("10")};var weight by remember{mutableStateOf("0")};var seconds by remember{mutableStateOf(0)};var running by remember{mutableStateOf(false)};LaunchedEffect(running){while(running&&seconds>0){kotlinx.coroutines.delay(1000);seconds--;if(seconds==0)running=false}};Column{Top(if(vm.arabic)e.ar else e.en,back={vm.screen="library"},action={vm.toggleFavorite(e)});LazyColumn(contentPadding=PaddingValues(start=16.dp,end=16.dp,bottom=24.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{AnimationPanel(e)};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){InfoChip(e.target);InfoChip(e.equipment)} };item{Text(if(vm.arabic)"التعليمات" else "Instructions",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)};items(e.instructions){Text("• $it",color=TextMuted)};item{Text(if(vm.arabic)"نصائح التقنية" else "Technique tips",fontWeight=FontWeight.Bold);Text(e.tips,color=TextMuted)};item{Text(if(vm.arabic)"الأخطاء الشائعة" else "Common mistakes",fontWeight=FontWeight.Bold);Text(e.mistakes,color=TextMuted)};item{Tracker(sets,reps,weight,{sets=it},{reps=it},{weight=it},{vm.complete()})};item{Row(verticalAlignment=Alignment.CenterVertically){Button({seconds=60;running=true},colors=ButtonDefaults.buttonColors(containerColor=Red)){Text(if(vm.arabic)"راحة 60 ثانية" else "60s rest")};Spacer(Modifier.width(14.dp));if(seconds>0)Text("${seconds}s",color=Red,fontWeight=FontWeight.Bold)}}}}}
@Composable fun AnimationPanel(e:Exercise){Card(Modifier.fillMaxWidth().height(220.dp),colors=CardDefaults.cardColors(containerColor=Color(0xFF111114)),shape=RoundedCornerShape(22.dp)){Column(Modifier.fillMaxSize(),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Icon(Icons.Default.AccessibilityNew,null,tint=Red,modifier=Modifier.size(72.dp));Text("3D MOVEMENT",color=Red,fontWeight=FontWeight.Bold,letterSpacing=2.sp);Text("Original animation asset pending",color=TextMuted,style=MaterialTheme.typography.bodySmall);Text(e.en,color=TextMuted,style=MaterialTheme.typography.labelSmall)}}}
@Composable fun InfoChip(t:String){Text(t,Modifier.background(Color(0xFF351016),RoundedCornerShape(50)).padding(horizontal=12.dp,vertical=7.dp),color=Red,style=MaterialTheme.typography.labelSmall)}
@Composable fun Tracker(sets:String,reps:String,weight:String,onSets:(String)->Unit,onReps:(String)->Unit,onWeight:(String)->Unit,complete:()->Unit){Card(colors=CardDefaults.cardColors(containerColor=Card),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("Workout tracker",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(sets,onSets,Modifier.weight(1f),label={Text("Sets")},singleLine=true);OutlinedTextField(reps,onReps,Modifier.weight(1f),label={Text("Reps")},singleLine=true);OutlinedTextField(weight,onWeight,Modifier.weight(1f),label={Text("kg")},singleLine=true)};Button(onClick=complete,colors=ButtonDefaults.buttonColors(containerColor=Red),modifier=Modifier.fillMaxWidth()){Text("Mark workout complete")}}}}
@Composable fun BottomNav(vm:GymVm){NavigationBar(containerColor=Charcoal){listOf("Home" to Icons.Default.Home,"Chest" to Icons.Default.FitnessCenter,"Favorites" to Icons.Default.Favorite,"History" to Icons.Default.History).forEachIndexed{idx,(name,icon)->NavigationBarItem(selected=(vm.screen==listOf("home","library","favorites","history")[idx]),onClick={vm.screen=listOf("home","library","favorites","history")[idx]},icon={Icon(icon,null)},label={Text(name)})}}}
